// Count last week's leads and write the Monday digest.
//
// "Last week" is the previous Monday to Sunday in the client's own time zone, so
// the message can say "Sep 21-27" and mean exactly that. Nothing here is
// estimated by AI: it is a count of the Lead Log, so it cannot be wrong.

const ZONE = 'America/Los_Angeles';
const now = DateTime.now().setZone(ZONE);
const weekEnd = now.startOf('week');            // this Monday 00:00
const weekStart = weekEnd.minus({ weeks: 1 });  // last Monday 00:00

// The Sheet can hand a timestamp back as an ISO string, as formatted text, or as
// a spreadsheet serial number, depending on how the cell was written. Accept all
// three rather than silently dropping rows.
function parseWhen(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number') {
    return DateTime.fromMillis(Math.round((value - 25569) * 86400000), { zone: 'utc' });
  }
  const text = String(value).trim();
  for (const parse of [
    () => DateTime.fromISO(text, { zone: 'utc' }),
    () => DateTime.fromSQL(text, { zone: 'utc' }),
    () => DateTime.fromFormat(text, 'M/d/yyyy H:mm:ss', { zone: 'utc' }),
  ]) {
    const when = parse();
    if (when.isValid) return when;
  }
  return null;
}

function inLastWeek(value) {
  const when = parseWhen(value);
  return Boolean(when) && when >= weekStart && when < weekEnd;
}

// Telegram is sent as HTML, so anything a lead typed must be escaped.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Webhook leads say which platform they came from ("facebook-ads"), which is what
// the owner actually wants to know; form and email are their own source.
function sourceLabel(row) {
  const source = String(row.source || '').toLowerCase();
  if (source === 'form') return 'Form';
  if (source === 'email') return 'Email';
  const detail = String(row.source_detail || '').trim();
  const name = detail && detail !== 'unknown' ? detail : source || 'unknown';
  return name.replace(/[-_]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

// A sheet with no data rows still produces one empty item (alwaysOutputData), so
// rows without a timestamp are not leads.
const leads = $('Read the Lead Log').all()
  .map((item) => item.json)
  .filter((row) => inLastWeek(row.received_at));

const waiting = $('Read the Quarantine tab').all()
  .map((item) => item.json)
  .filter((row) => row.failed_at && String(row.status || '').toLowerCase() === 'new');

const tiers = { hot: 0, warm: 0, cold: 0, unscored: 0 };
const sources = {};
let returning = 0;
for (const row of leads) {
  // The log writes "hot (returning)" for a repeat contact.
  const tierText = String(row.tier || '').toLowerCase();
  const tier = Object.keys(tiers).find((t) => tierText.startsWith(t)) || 'unscored';
  tiers[tier] += 1;
  if (tierText.includes('returning')) returning += 1;
  const label = sourceLabel(row);
  sources[label] = (sources[label] || 0) + 1;
}

const topHot = leads
  .filter((row) => String(row.tier || '').toLowerCase().startsWith('hot'))
  .sort((a, b) => (Number(b.score) || 0) - (Number(a.score) || 0))
  .slice(0, 3);

const lastDay = weekEnd.minus({ days: 1 });
const range = weekStart.month === lastDay.month
  ? `${weekStart.toFormat('MMM d')}–${lastDay.toFormat('d')}`
  : `${weekStart.toFormat('MMM d')} – ${lastDay.toFormat('MMM d')}`;

const lines = [`📊 <b>Weekly leads · ${range}</b>`, ''];

if (leads.length === 0) {
  // Still sent: silence would look the same as a broken workflow.
  lines.push('No new leads last week.');
} else {
  const tierParts = [`🔥 ${tiers.hot} hot`, `${tiers.warm} warm`, `${tiers.cold} cold`];
  if (tiers.unscored) tierParts.push(`${tiers.unscored} unscored`);
  lines.push(`<b>${leads.length} lead${leads.length === 1 ? '' : 's'}</b>: ${tierParts.join(' · ')}`);
  lines.push(Object.entries(sources)
    .sort((a, b) => b[1] - a[1])
    .map(([name, count]) => `${esc(name)} ${count}`)
    .join(' · '));
  if (returning) lines.push(`🔁 ${returning} from returning contacts`);

  if (topHot.length) {
    lines.push('', '<b>Top hot leads</b>');
    topHot.forEach((row, i) => {
      const who = row.company || [row.first_name, row.last_name].filter(Boolean).join(' ') || row.email;
      const reason = String(row.reason || '');
      const short = reason.length > 110 ? reason.slice(0, 107).replace(/\s+\S*$/, '') + '…' : reason;
      lines.push(`${i + 1}. <b>${esc(who)}</b> – ${esc(row.score)}/10${short ? ` – ${esc(short)}` : ''}`);
    });
  }
}

lines.push('');
lines.push(waiting.length
  // Crash rows sit here too, not only leads, hence "items".
  ? `⚠️ ${waiting.length} item${waiting.length === 1 ? '' : 's'} waiting in the Quarantine tab`
  : '✅ Nothing waiting in Quarantine');

return [{
  json: {
    text: lines.join('\n'),
    week_start: weekStart.toISODate(),
    week_end: lastDay.toISODate(),
    total: leads.length,
    tiers,
    sources,
    returning,
    quarantined: waiting.length,
  },
}];
